        "ui.driverAdviceCleared": { en: "NvStrapsReBar turned expansion off after a BIOS setup change or CMOS reset. Check your BIOS settings, then turn expansion back on and save.", ko: "BIOS 설정을 바꾸거나 CMOS를 초기화해서 NvStrapsReBar가 확장을 껐습니다. BIOS 설정을 확인한 뒤 확장을 다시 켜고 저장하세요." },
        "ui.driverAdviceGpuUnconfigured": { en: "The saved configuration has no GPU details. Saving again from BAR Settings fills them in.", ko: "저장된 설정에 GPU 정보가 비어 있습니다. BAR 설정에서 다시 저장하면 채워집니다." },
        "ui.driverAdviceStrapsUnconfirmed": { en: "The selected size has not been confirmed. Try choosing a target PCI BAR size.", ko: "선택한 크기가 적용되었는지 확인되지 않았습니다. 대상 PCI BAR 크기를 직접 지정해 보세요." },
        "ui.driverAdviceCapabilityMissing": { en: "The GPU does not list adjustable BAR sizes. Try “Allow sizes not listed by the GPU.”", ko: "GPU가 조절 가능한 BAR 크기를 표시하지 않습니다. ‘GPU 지원 목록에 없는 크기 허용’을 사용해 보세요." },
        "ui.driverAdviceHardwareMismatch": { en: "The saved configuration no longer matches the hardware — this happens after changing GPUs or slots. Refresh the system and save again.", ko: "저장된 설정이 지금 하드웨어와 맞지 않습니다. GPU나 슬롯을 바꾼 뒤에 생기는 상태이니, 시스템을 새로 고치고 다시 저장하세요." },
        "ui.driverAdviceSetupVariable": { en: "BIOS settings changes could not be detected. Turning off “Turn off expansion if BIOS settings change” skips this check.", ko: "BIOS 설정 변경을 감지하지 못했습니다. ‘BIOS 설정이 바뀌면 확장 끄기’를 끄면 이 확인을 건너뜁니다." },
